CREATE COLUMN TABLE "TEST_AP"."OALC" ("AlcCode" NVARCHAR(2) NOT NULL , "AlcName" NVARCHAR(30), "OhType" NVARCHAR(1) DEFAULT 'F', "AcctCode" NVARCHAR(15), "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LaCAllcAcc" NVARCHAR(15), "CostCateg" NVARCHAR(1), PRIMARY KEY ("AlcCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OALC_GROUP_NAME" ON "TEST_AP"."OALC" ( "AlcName" ASC )